package ai.decisionos.aside;
import android.os.*;import org.json.*;import java.util.*;import java.lang.ref.WeakReference;
/** One foreground browser lease; durable ownership survives UI selection and Activity replacement. */
final class RunCoordinator {
 final GoalStore store;final Handler handler=new Handler(Looper.getMainLooper());WeakReference<GoalAgentActivity> host=new WeakReference<>(null);JSONObject run;boolean polling,closed;int errors;String notice="";
 RunCoordinator(GoalAgentActivity a){store=new GoalStore(a.getApplicationContext());host=new WeakReference<>(a);for(JSONObject row:store.workspace("runs",null))if(!row.optBoolean("legacy")&&live(row.optString("state"))){run=row;break;}}
 static boolean live(String state){return Arrays.asList("QUEUED","RUNNING","WAITING_USER","STOP_REQUESTED","OUTCOME_UNKNOWN").contains(state);}
 JSONObject active(){return run!=null&&live(run.optString("state"))?run:null;}
 boolean owns(String goal,String conversation){return active()!=null&&goal.equals(run.optString("goalId"))&&conversation.equals(run.optString("conversationId"));}
 String executionGoal(String selected){return active()==null?selected:run.optString("goalId");}
 void save(){if(run!=null){GoalStore.put(run,"updatedAt",System.currentTimeMillis());store.saveWorkspace("runs",run);}changed();}
 void changed(){GoalAgentActivity a=host.get();if(a!=null&&!a.isDestroyed()&&a.chat!=null)a.chat.syncRun();}
 void start(GoalChatUi chat,String text){startWithInstruction(chat,text,text);}
 void startWithInstruction(GoalChatUi chat,String text,String instruction){if(ChatWork.busy(chat.a)){chat.a.toast("자동봇 작업이 실행 중이에요. 대화에 결과를 가져올게요.");return;}if(active()!=null){chat.a.toast("다른 작업이 진행 중이에요. 실행 카드를 확인해 주세요.");return;}if(chat.goalId.isEmpty()){chat.companion.purposePicker();return;}chat.save();GoalAgentActivity a=host.get();if(a==null||!a.relay.connected()){if(a!=null)a.pair();return;}StringBuilder context=new StringBuilder();for(int n=Math.max(0,chat.history.length()-4);n<chat.history.length();n++){JSONObject m=chat.history.optJSONObject(n);if(m!=null&&!m.has("expiresAt")){String t=m.optString("text");context.append(m.optString("role")).append(": ").append(t.substring(0,Math.min(t.length(),200))).append('\n');}}String task=context.length()==0?instruction:"이전 대화 (참고이며 새 관측 근거 아님):\n"+context+"현재 사용자 지시:\n"+instruction;if(task.length()>2000){a.toast("이전 대화를 포함해 2000자 이내로 요청해 주세요.");return;}
  run=new JSONObject();GoalStore.put(run,"id",UUID.randomUUID().toString());GoalStore.put(run,"requestId",UUID.randomUUID().toString());GoalStore.put(run,"goalId",chat.goalId);GoalStore.put(run,"conversationId",chat.conversationId);GoalStore.put(run,"character",chat.character);GoalStore.put(run,"task",task);GoalStore.put(run,"deviceSession",a.relay.session());GoalStore.put(run,"text",text);GoalStore.put(run,"state","QUEUED");GoalStore.put(run,"steps",new JSONArray());GoalStore.put(run,"startedAt",System.currentTimeMillis());JSONObject user=chat.message("user",text);GoalStore.put(user,"runId",run.optString("id"));GoalStore.put(user,"state","running");GoalStore.put(run,"userMessageId",user.optString("id"));chat.history.put(user);store.saveConversation(chat.conversationId,chat.history,"");chat.input.setText("");a.gid=chat.goalId;a.invalidate();save();submit();}
 void submit(){GoalAgentActivity a=host.get();if(a==null||active()==null)return;final String id=run.optString("id");JSONObject body=new JSONObject();GoalStore.put(body,"goal_id",run.optString("goalId"));GoalStore.put(body,"character",run.optString("character"));GoalStore.put(body,"task",run.optString("task"));GoalStore.put(body,"request_id",run.optString("requestId"));a.relay.chat("/chat-submit",body,r->{if(!current(id))return;if(r.has("error")&&!r.isNull("error")){GoalStore.put(run,"state","OUTCOME_UNKNOWN");GoalStore.put(run,"detail","전달 결과 확인 필요 · 같은 요청 ID로 확인할 수 있어요.");save();return;}accept(r);});}
 boolean current(String id){return !closed&&run!=null&&id.equals(run.optString("id"));}
 void accept(JSONObject response){if(active()==null)return;String job=response.optString("job_id");if(!run.optString("goalId").equals(response.optString("goal_id"))||(!run.optString("jobId").isEmpty()&&!run.optString("jobId").equals(job))||(response.has("request_id")&&!run.optString("requestId").equals(response.optString("request_id")))){GoalStore.put(run,"state","OUTCOME_UNKNOWN");GoalStore.put(run,"detail","응답 소유권을 확인하지 못했어요.");save();return;}GoalStore.put(run,"jobId",job);JSONArray steps=response.optJSONArray("progress");if(steps!=null)GoalStore.put(run,"steps",steps);String state=response.optString("state");if(Arrays.asList("completed","failed","cancelled").contains(state)){complete(state,response);return;}if(!run.optString("state").equals("STOP_REQUESTED"))GoalStore.put(run,"state","RUNNING");save();schedule();}
 void complete(String state,JSONObject result){long expiry=result.optLong("expires_at");if(expiry>0)GoalStore.put(run,"expiresAt",expiry);GoalStore.put(run,"state",state.equals("completed")?"SUCCEEDED":state.equals("cancelled")?"STOPPED":"FAILED");String answer=state.equals("completed")?result.optString("answer"):state.equals("cancelled")?"서버에서 작업 중지를 확인했어요.":result.optString("error","실행 결과를 확인해 주세요.");answer=answer.replace("\\n","\n").replace("\\\"","\"");GoalStore.put(run,"answer",answer);GoalStore.put(run,"finishedAt",System.currentTimeMillis());JSONArray items=new JSONArray(),candidate=result.optJSONArray("items");JSONObject goal=store.goal(run.optString("goalId"));JSONArray observed=goal.optJSONArray("qwenSources");for(int n=0;candidate!=null&&n<candidate.length();n++){JSONObject item=candidate.optJSONObject(n);if(item==null)continue;for(int k=0;observed!=null&&k<observed.length();k++)if(item.optString("url").equals(observed.optString(k))){items.put(item);break;}}GoalStore.put(run,"items",items);JSONObject conversation=store.workspaceRow("conversations",run.optString("conversationId"));JSONArray history=conversation.optJSONArray("messages");if(history==null)history=new JSONArray();boolean exists=false;for(int n=0;n<history.length();n++){JSONObject m=history.optJSONObject(n);if(m==null)continue;if(m.optString("id").equals(run.optString("userMessageId")))GoalStore.put(m,"state",state);if(m.optString("runId").equals(run.optString("id"))&&m.optString("role").equals("assistant"))exists=true;}if(!exists){JSONObject message=new JSONObject();if(expiry>0)GoalStore.put(message,"expiresAt",expiry);GoalStore.put(message,"id",UUID.randomUUID().toString());GoalStore.put(message,"role","assistant");GoalStore.put(message,"text",answer);GoalStore.put(message,"state",state);GoalStore.put(message,"at",System.currentTimeMillis());GoalStore.put(message,"runId",run.optString("id"));GoalStore.put(message,"items",items);GoalStore.put(message,"steps",run.optJSONArray("steps"));JSONObject doc=result.optJSONObject("document");if(doc!=null){GoalStore.put(doc,"job_id",run.optString("jobId"));GoalStore.put(doc,"goalId",run.optString("goalId"));GoalStore.put(message,"document",doc);JSONObject patch=new JSONObject();GoalStore.put(patch,"documentResult",doc);GoalStore.put(patch,"qwenSummary",answer);store.patchGoal(run.optString("goalId"),patch);JSONObject artifact=GoalStore.json(doc.toString());GoalStore.put(artifact,"id","document-"+run.optString("id"));GoalStore.put(artifact,"goalId",run.optString("goalId"));GoalStore.put(artifact,"conversationId",run.optString("conversationId"));store.saveWorkspace("artifacts",artifact);}history.put(message);}store.saveConversation(conversation.optString("id"),history,conversation.optString("draft"));save();GoalAgentActivity a=host.get();if(a!=null)a.gid=a.chat.goalId;}
 void schedule(){handler.removeCallbacksAndMessages(null);handler.postDelayed(this::poll,1500);}
 void poll(){GoalAgentActivity a=host.get();if(a==null||active()==null||polling||a.isFinishing()||a.isDestroyed())return;String job=run.optString("jobId");if(job.isEmpty()){return;}final String id=run.optString("id");polling=true;a.relay.chat("/chat-status",new GoalChatUi.JSONObjectSafe("job_id",job),r->{polling=false;if(!current(id)||active()==null)return;if(r.has("error")&&!r.has("state")){if(++errors>=3){GoalStore.put(run,"state","OUTCOME_UNKNOWN");GoalStore.put(run,"detail","연결이 끊겼어요. 결과를 다시 확인해 주세요.");save();return;}schedule();return;}errors=0;accept(r);});}
 void cancel(){GoalAgentActivity a=host.get();if(a==null||active()==null)return;String job=run.optString("jobId");if(job.isEmpty()){GoalStore.put(run,"detail","전달 결과를 먼저 확인해야 중지할 수 있어요.");save();return;}final String id=run.optString("id");GoalStore.put(run,"state","STOP_REQUESTED");save();a.relay.chat("/chat-cancel",new GoalChatUi.JSONObjectSafe("job_id",job),r->{if(!current(id)||active()==null)return;if(r.has("state"))accept(r);else{GoalStore.put(run,"state","OUTCOME_UNKNOWN");GoalStore.put(run,"detail","중지 여부를 확인하지 못했어요. 결과 재확인이 필요해요.");save();}});}
 void retryStatus(){if(active()==null)return;errors=0;if(run.optString("jobId").isEmpty())submit();else poll();}
 void pause(){if(active()!=null&&!run.optString("state").equals("STOP_REQUESTED")&&!run.optString("state").equals("OUTCOME_UNKNOWN")){GoalStore.put(run,"state","WAITING_USER");GoalStore.put(run,"detail","앱이 가려졌어요. 복귀 후 서버 결과를 확인해요.");save();}handler.removeCallbacksAndMessages(null);}
 void resume(){if(active()!=null){GoalAgentActivity a=host.get();if(a!=null)a.gid=run.optString("goalId");if(!run.optString("jobId").isEmpty())poll();else{GoalStore.put(run,"state","OUTCOME_UNKNOWN");GoalStore.put(run,"detail","전달 상태 확인 필요 · 동일 요청으로 확인");save();}}}
 void detach(){closed=true;handler.removeCallbacksAndMessages(null);host.clear();store.close();}
}
